<?php $pages = max( 1, (int) ceil( $history['total'] / $history['per_page'] ) ); ?>
<form method="get" data-admitad-ajax data-admitad-action="promokodiki_admitad_admin" data-admitad-operation="history_list" data-admitad-page="admitad-history" data-admitad-fragment="history-table"><input type="hidden" name="post_type" value="promocode"><input type="hidden" name="page" value="admitad-history"><input type="hidden" name="snapshot" value="<?php echo esc_attr( $request->filter( 'snapshot' ) ); ?>"><label>Строк на странице <select name="per_page"><?php foreach ( array( 20, 50, 100 ) as $size ) : ?><option value="<?php echo esc_attr( (string) $size ); ?>"<?php selected( $request->per_page(), $size ); ?>><?php echo esc_html( (string) $size ); ?></option><?php endforeach; ?></select></label><button class="button">Применить</button></form>
<table class="widefat striped"><thead><tr><th>ID</th><th>Купон</th><th>Триггер / уверенность</th><th>Было → стало</th><th>Дата</th></tr></thead><tbody><?php if ( empty( $history['items'] ) ) : ?><tr><td colspan="5">История пуста.</td></tr><?php endif; foreach ( $history['items'] as $row ) : $confidence = Promokodiki_Admitad_Admin_Presenter::status( 'confidence', $row['confidence'] ); ?><tr><td><?php echo esc_html( (string) $row['id'] ); ?></td><td><?php if ( $row['view_url'] ) : ?><a href="<?php echo esc_url( $row['view_url'] ); ?>"><?php echo esc_html( $row['title'] . ' (#' . $row['post_id'] . ')' ); ?></a><?php else : ?><?php echo esc_html( (string) $row['post_id'] ); ?><?php endif; ?><?php if ( $row['edit_url'] ) : ?> <a href="<?php echo esc_url( $row['edit_url'] ); ?>">Редактировать</a><?php endif; ?></td><td><?php echo esc_html( $row['trigger_name'] ); ?><br><span class="<?php echo esc_attr( $confidence['class'] ); ?>"><?php echo esc_html( $confidence['label'] ); ?></span></td><td><?php echo esc_html( $row['previous_paths'] . ' → ' . $row['result_paths'] ); ?></td><td><?php echo esc_html( $row['created_at'] ); ?></td></tr><?php endforeach; ?></tbody></table>
<?php if ( $pages > 1 ) : ?><nav><?php for ( $i = 1; $i <= $pages; ++$i ) : $url = add_query_arg( 'paged', $i, $request->url() ); ?><a href="<?php echo esc_url( $url ); ?>" data-admitad-ajax data-admitad-action="promokodiki_admitad_admin" data-admitad-operation="history_list" data-admitad-page="admitad-history" data-admitad-fragment="history-table"><?php echo esc_html( (string) $i ); ?></a> <?php endfor; ?></nav><?php endif; ?>
